using Myriale.Api.Architecture; namespace Myriale.Api.Features.Scenarios; [FeatureSlice("Scenarios")] public static class ScenariosFeature { public static IServiceCollection AddScenariosFeature(this IServiceCollection s){s.AddSingleton<ScenarioRuleJsonCodec>();s.AddScoped<IScenarioDefinitionRepository,EfScenarioDefinitionRepository>();s.AddScoped<ScenarioDefinitionMapper>();s.AddScoped<ScenarioProfileConfigurationResolver>();s.AddScoped<ScenarioDefinitionValidator>();s.AddScoped<ScenarioDefinitionWriter>();s.AddScoped<ScenarioDefinitionDraftService>();s.AddScoped<ScenarioDefinitionQueryService>();s.AddScoped<ScenarioQueryService>();s.AddScoped<ScenarioNarrativeTestService>();s.AddScoped<ScenarioAiEvaluationService>();s.AddScoped<CreateScenarioUseCase>();s.AddScoped<UpdateScenarioUseCase>();s.AddScoped<CreateScenarioDefinitionDraftUseCase>();s.AddScoped<SaveScenarioDefinitionUseCase>();s.AddScoped<PublishScenarioDefinitionUseCase>();s.AddScoped<ScenarioDefinitionReadinessPolicy>();s.AddScoped<IDomainEventDispatcher,DomainEventDispatcher>();s.AddScoped<IDomainEventHandler<ScenarioDefinitionPublished>,ScenarioDefinitionPublishedLoggingHandler>();s.AddScoped<ScenarioRuleConfigurationResolver>();s.AddScoped<ScenarioRuleDebugService>();return s;} public static IEndpointRouteBuilder MapScenariosFeature(this IEndpointRouteBuilder e){e.MapScenarioEndpoints();e.MapScenarioAiEndpoints();e.MapScenarioAiEvaluationEndpoints();return e;} }
